export type TaskLedgerEventType =
  | "submitted"
  | "accepted"
  | "rejected"
  | "started"
  | "completed"
  | "failed"
  | "cancelled";

export interface TaskLedgerEvent {
  eventId: string;
  workspaceId: string;
  batchIdempotencyKey: string;
  type: TaskLedgerEventType;
  occurredAt: string;
  payload?: Record<string, unknown>;
}

export interface WorkingContextTask {
  eventId: string;
  workspaceId: string;
  batchIdempotencyKey: string;
  type: TaskLedgerEventType;
  occurredAt: string;
  status: "pending" | "accepted" | "rejected" | "running" | "completed" | "failed" | "cancelled";
  payload?: Record<string, unknown>;
}

export interface TaskLedgerWorkingContextView {
  workspaceId: string;
  tasks: WorkingContextTask[];
  pending: WorkingContextTask[];
  accepted: WorkingContextTask[];
}

/**
 * Projects ledger events into a working-context view. The ledger remains the only
 * source of truth; this function deliberately contains no persistence logic.
 * Duplicate batches are collapsed by their idempotency key and the first event
 * in a batch wins.
 */
export function projectTaskLedgerWorkingContext(
  workspaceId: string,
  events: readonly TaskLedgerEvent[],
): TaskLedgerWorkingContextView {
  const batches = new Map<string, TaskLedgerEvent>();

  for (const event of events) {
    if (event.workspaceId !== workspaceId || !event.batchIdempotencyKey) continue;
    if (!batches.has(event.batchIdempotencyKey)) {
      batches.set(event.batchIdempotencyKey, event);
    }
  }

  const tasks = Array.from(batches.values())
    .map((event) => ({
      eventId: event.eventId,
      workspaceId: event.workspaceId,
      batchIdempotencyKey: event.batchIdempotencyKey,
      type: event.type,
      occurredAt: event.occurredAt,
      status: statusForEvent(event.type),
      ...(event.payload === undefined ? {} : { payload: event.payload }),
    }))
    .sort(compareTasks);

  return {
    workspaceId,
    tasks,
    pending: tasks.filter((task) => task.status === "pending"),
    accepted: tasks.filter((task) => task.status === "accepted"),
  };
}

function statusForEvent(type: TaskLedgerEventType): WorkingContextTask["status"] {
  switch (type) {
    case "submitted": return "pending";
    case "accepted": return "accepted";
    case "rejected": return "rejected";
    case "started": return "running";
    case "completed": return "completed";
    case "failed": return "failed";
    case "cancelled": return "cancelled";
  }
}

function compareTasks(a: WorkingContextTask, b: WorkingContextTask): number {
  const byTime = a.occurredAt.localeCompare(b.occurredAt);
  return byTime || a.eventId.localeCompare(b.eventId);
}

export const projectWorkingContext = projectTaskLedgerWorkingContext;

import { appendFile, mkdir, readFile } from "node:fs/promises";
import path from "node:path";
import {
  projectTaskLedgerWorkingContext,
  type TaskLedgerEvent,
  type TaskLedgerWorkingContextView,
} from "../../shared/task-ledger-working-context";

export interface TaskLedgerWorkingContextOptions {
  /** Root containing the existing workspace ledger directory. */
  workspaceRoot: string;
  /** Optional explicit ledger path. Otherwise a workspace-isolated JSONL file is used. */
  ledgerPath?: string;
}

export interface AppendTaskLedgerEventInput {
  workspaceId: string;
  batchIdempotencyKey: string;
  type: TaskLedgerEvent["type"];
  payload?: Record<string, unknown>;
  eventId?: string;
  occurredAt?: string;
}

/**
 * JSONL-backed adapter for the existing workspace Task Ledger. It owns no
 * snapshot or alternate store: reads always replay the ledger and writes are
 * appended to the ledger itself.
 */
export class TaskLedgerWorkingContext {
  private readonly workspaceRoot: string;
  private readonly explicitLedgerPath?: string;
  private appendQueue: Promise<void> = Promise.resolve();

  constructor(options: TaskLedgerWorkingContextOptions) {
    this.workspaceRoot = path.resolve(options.workspaceRoot);
    this.explicitLedgerPath = options.ledgerPath
      ? path.resolve(options.ledgerPath)
      : undefined;
  }

  ledgerPathFor(workspaceId: string): string {
    if (this.explicitLedgerPath) return this.explicitLedgerPath;
    const safeWorkspaceId = workspaceId.replace(/[^a-zA-Z0-9._-]/g, "_");
    return path.join(this.workspaceRoot, "task-ledger", `${safeWorkspaceId}.jsonl`);
  }

  async append(input: AppendTaskLedgerEventInput): Promise<TaskLedgerEvent> {
    if (!input.workspaceId) throw new Error("workspaceId is required");
    if (!input.batchIdempotencyKey) throw new Error("batchIdempotencyKey is required");

    const event: TaskLedgerEvent = {
      eventId: input.eventId ?? createEventId(),
      workspaceId: input.workspaceId,
      batchIdempotencyKey: input.batchIdempotencyKey,
      type: input.type,
      occurredAt: input.occurredAt ?? new Date().toISOString(),
      ...(input.payload === undefined ? {} : { payload: input.payload }),
    };

    const operation = this.appendQueue.then(async () => {
      const ledgerPath = this.ledgerPathFor(input.workspaceId);
      const existing = await this.readEventsFrom(ledgerPath, input.workspaceId);
      if (existing.some((item) => item.batchIdempotencyKey === input.batchIdempotencyKey)) {
        return;
      }

      await mkdir(path.dirname(ledgerPath), { recursive: true });
      await appendFile(ledgerPath, `${JSON.stringify(event)}\n`, { encoding: "utf8", flag: "a" });
    });

    this.appendQueue = operation.catch(() => undefined);
    await operation;
    return event;
  }

  async read(workspaceId: string): Promise<TaskLedgerEvent[]> {
    if (!workspaceId) throw new Error("workspaceId is required");
    return this.readEventsFrom(this.ledgerPathFor(workspaceId), workspaceId);
  }

  async projection(workspaceId: string): Promise<TaskLedgerWorkingContextView> {
    const events = await this.read(workspaceId);
    return projectTaskLedgerWorkingContext(workspaceId, events);
  }

  private async readEventsFrom(ledgerPath: string, workspaceId: string): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await readFile(ledgerPath, "utf8");
    } catch (error) {
      if (isMissingFileError(error)) return [];
      throw error;
    }

    const events: TaskLedgerEvent[] = [];
    const lines = contents.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index].trim();
      if (!line) continue;
      let parsed: unknown;
      try {
        parsed = JSON.parse(line);
      } catch {
        throw new Error(`Invalid task ledger JSONL at ${ledgerPath}:${index + 1}`);
      }
      if (!isTaskLedgerEvent(parsed)) {
        throw new Error(`Invalid task ledger event at ${ledgerPath}:${index + 1}`);
      }
      if (parsed.workspaceId === workspaceId) events.push(parsed);
    }
    return events;
  }
}

function isMissingFileError(error: unknown): boolean {
  return typeof error === "object" && error !== null && "code" in error && (error as { code?: unknown }).code === "ENOENT";
}

function isTaskLedgerEvent(value: unknown): value is TaskLedgerEvent {
  if (typeof value !== "object" || value === null) return false;
  const event = value as Partial<TaskLedgerEvent>;
  return (
    typeof event.eventId === "string" &&
    typeof event.workspaceId === "string" &&
    typeof event.batchIdempotencyKey === "string" &&
    typeof event.type === "string" &&
    typeof event.occurredAt === "string"
  );
}

function createEventId(): string {
  const random = Math.random().toString(36).slice(2);
  return `${Date.now().toString(36)}-${random}`;
}

export { projectTaskLedgerWorkingContext } from "../../shared/task-ledger-working-context";
export type { TaskLedgerEvent, TaskLedgerWorkingContextView } from "../../shared/task-ledger-working-context";

